/* Project model. Independent of the UI and browser audio. */
(()=>{const rack=value=>Array.from({length:2},(_,i)=>typeof PocketFX!=='undefined'?PocketFX.normalized(value?.[i]):{type:'off',amount:.4,character:.35,wet:.35});const midi=value=>({input:String(value?.input||'').slice(0,200),output:String(value?.output||'').slice(0,200),mode:['bank','all','keys'].includes(value?.mode)?value.mode:'bank',channel:Math.max(0,Math.min(16,Math.round(Number(value?.channel)||0))),outChannel:Math.max(1,Math.min(16,Math.round(Number(value?.outChannel)||1))),notesOut:!!value?.notesOut,clockIn:!!value?.clockIn,clockOut:!!value?.clockOut});const cloneSlot=p=>({...p,...(p.params?{params:{...p.params}}:{})});const blank=()=>({fx:rack(),name:'Vide',data:new Float32Array(1),right:null,start:0,end:1,volume:.8,pitch:0,pan:0,attack:3,release:35,mode:'one',muted:false,solo:false,choke:0});
const fresh=()=>({format:'pocket-studio',version:1,name:'Nouvelle idée',masterFX:rack(),midi:midi(),bpm:112,bank:0,selected:0,pattern:0,kit:'House',recordGrid:1,pads:Array.from({length:64},blank),patterns:Array.from({length:8},(_,i)=>({name:'Boucle '+(i+1),bars:1,notes:[]}))});
const clone=s=>({...s,masterFX:rack(s.masterFX).map(cloneSlot),midi:midi(s.midi),pads:s.pads.map(p=>({...p,fx:rack(p.fx).map(cloneSlot)})),patterns:s.patterns.map(p=>({...p,notes:p.notes.map(n=>({...n}))}))});
const bound=(v,a,b,d)=>Number.isFinite(v)?Math.min(b,Math.max(a,v)):d;
function validate(raw,decode=x=>x){if(raw?.format!=='pocket-studio'||raw.version!==1||!Array.isArray(raw.pads)||raw.pads.length!==64||!Array.isArray(raw.patterns)||raw.patterns.length!==8)throw Error('Ce fichier n’est pas un projet Pocket Studio.');let total=0;const s=fresh();Object.assign(s,{masterFX:rack(raw.masterFX),midi:midi(raw.midi),name:String(raw.name||'Mon idée').slice(0,48),bpm:bound(raw.bpm,40,220,112),bank:Math.round(bound(raw.bank,0,3,0)),selected:Math.round(bound(raw.selected,0,63,0)),pattern:Math.round(bound(raw.pattern,0,7,0)),kit:String(raw.kit||'Mes sons').slice(0,30),recordGrid:[0,.5,1,2].includes(raw.recordGrid)?raw.recordGrid:1});s.pads=raw.pads.map(p=>{const data=decode(p.data),right=p.right?decode(p.right):null;if(!(data instanceof Float32Array)||!data.length||data.length>44100*60||right&&(!(right instanceof Float32Array)||right.length!==data.length))throw Error('Sample invalide ou supérieur à 60 secondes.');total+=data.length+(right?.length||0);if(total>44100*240)throw Error('Projet trop volumineux pour ce studio mobile.');for(const d of [data,right])if(d)for(const x of d)if(!Number.isFinite(x)||Math.abs(x)>32)throw Error('Signal audio invalide.');const start=bound(p.start,0,.99999,0),end=bound(p.end,0,1,1);if(end<=start)throw Error('Bornes du sample invalides.');return {...blank(),fx:rack(p.fx),name:String(p.name||'Son').slice(0,30),data,right,start,end,volume:bound(p.volume,0,1.5,.8),pitch:bound(p.pitch,-24,24,0),pan:bound(p.pan,-1,1,0),attack:bound(p.attack,0,1000,3),release:bound(p.release,5,2000,35),mode:['one','hold','loop'].includes(p.mode)?p.mode:'one',muted:!!p.muted,solo:!!p.solo,choke:Math.round(bound(p.choke,0,8,0))}});s.patterns=raw.patterns.map((p,i)=>{const bars=Math.round(bound(p.bars,1,4,1));if(!Array.isArray(p.notes)||p.notes.length>8192)throw Error('Boucle trop volumineuse.');return {name:String(p.name||'Boucle '+(i+1)).slice(0,24),bars,notes:p.notes.filter(n=>Number.isInteger(n.pad)&&n.pad>=0&&n.pad<64&&Number.isFinite(n.step)&&n.step>=0&&n.step<bars*16).map(n=>({pad:n.pad,step:Math.min(bars*16-1/24,Math.round(n.step*24)/24),pitch:bound(n.pitch,-24,24,0),velocity:bound(n.velocity,.05,1,1),duration:bound(n.duration,1/24,64,.9),gated:!!n.gated}))}});return s}
function put(pattern,note){const found=pattern.notes.findIndex(n=>n.pad===note.pad&&Math.abs(n.step-note.step)<1/48&&n.pitch===note.pitch);if(found>=0)pattern.notes[found]={...note};else{if(pattern.notes.length>=8192)throw Error('Cette boucle est pleine.');pattern.notes.push({...note})}}
function legacy(o,decode){if(o?.format!=='pocket-sample'||!Array.isArray(o.pads))throw Error('Projet non reconnu.');const s=fresh();s.name=String(o.name||'Idée importée');s.bpm=o.bpm||112;s.kit='Import Pocket Sample';s.pads=Array.from({length:64},(_,i)=>{const p=o.pads[i];if(!p)return blank();return {...blank(),...p,fx:rack([p.padFX]),data:decode(p.data),right:p.right?decode(p.right):null,mode:p.mode==='gate'?'hold':p.mode==='toggle'?'loop':'one',choke:p.chokeGroup||0}});for(let pat=0;pat<8;pat++){const bars=Math.min(4,o.sequenceBars?.[pat]||1);s.patterns[pat].bars=bars;for(let i=0;i<64;i++)for(let step=0;step<bars*16;step++)if(o.pads[i]?.patterns?.[pat]?.[step]){const e=o.pads[i].events?.[pat+':'+step]||{};for(const n of [e,...(e.extra||[])])put(s.patterns[pat],{pad:i,step:Math.max(0,Math.min(bars*16-1/24,step+(n.offset||0))),pitch:n.pitch||0,velocity:(n.velocity||127)/127,duration:n.duration||.9})}}return validate(s)}
globalThis.StudioModel={rack,midi,blank,fresh,clone,validate,put,legacy,bound};})();
